% MAIN ENTRY — 项目主文档，唯一入口
% Current course lecture notes live here.
% Compile THIS file. Content: sections/lecture.tex (+ exercises).
% NOTE: old_main.tex is deprecated and must NOT be used as an entry.
% ============================================================
\documentclass{article}
\begin{document}
\input{sections/lecture}
\end{document}

% ============================================================
% DEPRECATED — 已废弃备份，切勿编译 / DO NOT COMPILE
%
% This file was once a main entry and is kept only as a backup
% reference. To remove the confusing duplicate entry, its LaTeX
% scaffolding is commented out so it can no longer be compiled
% or mistaken for the main document.
%
% The single main entry is: main.tex
%   main.tex -> \input{sections/lecture.tex}
%            -> \input{sections/exercises.tex}
% ============================================================
% \documentclass{article}
% \begin{document}
% Backup entry; do not use as the current lecture.
% \end{document}

\section{Current lecture}
The current lecture content remains in this section file.
\input{sections/exercises}
